'use strict';
// Tana platform protobuf descriptors, extracted from the home.tana.inc web client (v1alpha1, undocumented).
// Loaded at runtime with @bufbuild/protobuf's fileDesc, so no codegen step is needed.
const { fileDesc } = require('@bufbuild/protobuf/codegenv2');
const wkt = require('@bufbuild/protobuf/wkt');

// buf/validate/validate.proto (dependency only)
const validate = fileDesc("", [wkt.file_google_protobuf_descriptor, wkt.file_google_protobuf_duration, wkt.file_google_protobuf_timestamp]);

// tana/sync/v1alpha1/sync.proto
const sync = fileDesc("", [validate]);

// tana/graph/v1alpha1/graph.proto
const graph = fileDesc("", [wkt.file_google_protobuf_timestamp, validate]);

// tana/search/v1alpha1/search.proto
const search = fileDesc("", [validate]);

// tana/history/v1alpha1/changes.proto
const history = fileDesc("", [wkt.file_google_protobuf_timestamp, validate]);

// tana/acl/v1alpha1/acl.proto
const acl = fileDesc("", [validate]);

const files = { sync, graph, search, history, acl };
const message = (file, name) => {
  const m = files[file].messages.find((m) => m.name === name);
  if (!m) throw new Error('unknown message ' + file + '.' + name);
  return m;
};

module.exports = {
  files,
  message,
  SyncService: sync.services[0],
  GraphService: graph.services[0],
  SearchService: search.services[0],
  ChangeSummaryService: history.services[0],
  ACLService: acl.services[0],
};
